-- Add missing item_enchantment_template rows for RandomSuffix/RandomProperty groups
-- referenced by item_template, and clear invalid random enchant fields on test items.
-- Craft groups 415/416 use the same enchant pool as existing craftable random-suffix group 451.

DELETE FROM `item_enchantment_template` WHERE `entry` IN (
  390,391,392,393,394,395,396,397,398,399,400,401,402,403,404,405,406,407,408,409,410,411,412,
  414,415,416,417,418,419,420,421,422,423,424,425,426,427,429,431,432,433,434,435,437,438,439,
  440,441,442,450,451,557,558,578,641,642,643,644,645,646,647,648
);


-- Clear invalid random enchant references on unused/test items and broken property IDs.
UPDATE `item_template` SET `RandomSuffix` = 0 WHERE `RandomSuffix` IN (102,103,105,121);
UPDATE `item_template` SET `RandomProperty` = 0 WHERE `entry` IN (1259,17982) AND `RandomProperty` IN (2191,3474);
